const binaryKeys = Object.keys($binary || {});
if (binaryKeys.length === 0) {
  return [{
    json: {
      statusCode: 400,
      response: {
        success: false,
        message: '未偵測到上傳的檔案！'
      }
    }
  }];
}

const firstKey = binaryKeys[0];
const fileInfo = $binary[firstKey];
const sizeMb = (fileInfo.fileSize / 1024 / 1024).toFixed(2) + ' MB';
const fakeFileId = '1DriveFile_' + Date.now();
const fileUrl = 'https://drive.google.com/file/d/' + fakeFileId + '/view';

return [{
  json: {
    statusCode: 200,
    response: {
      success: true,
      message: '檔案已成功上傳並完成雲端硬碟託管！',
      fileName: fileInfo.fileName || 'uploaded_file',
      fileSize: sizeMb,
      mimeType: fileInfo.mimeType,
      fileUrl: fileUrl
    }
  },
  binary: $binary
}];
